--
-- Table structure for table `repair_item`
--

DROP TABLE IF EXISTS `repair_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `repair_item` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `item_name` varchar(255) NOT NULL COMMENT '修理名称',
  `std_id` int DEFAULT NULL COMMENT '标准修理单id',
  `is_std` int DEFAULT NULL COMMENT '是否匹配标准修理单',
  `std_name` varchar(255) DEFAULT NULL COMMENT '标准修理单名称',
  `item_order` int DEFAULT NULL COMMENT '序号',
  `item_content` varchar(255) DEFAULT NULL COMMENT '规格型号',
  `category_id` int DEFAULT NULL COMMENT '维修类别',
  `unit` varchar(50) DEFAULT NULL COMMENT '单位',
  `count` decimal(10,2) DEFAULT NULL COMMENT '数量',
  `price` decimal(10,2) DEFAULT NULL COMMENT '价格',
  `max_price` decimal(10,2) DEFAULT NULL COMMENT '最高限价',
  `remark` text COMMENT '备注',
  `order_id` int DEFAULT NULL,
  `audit_state` int DEFAULT '0' COMMENT '审核状态',
  `delete_state` int DEFAULT '0' COMMENT '删除状态',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  `update_user` varchar(100) DEFAULT NULL COMMENT '最后更新人员',
  PRIMARY KEY (`id`),
  KEY `repair_item_FK` (`order_id`),
  CONSTRAINT `repair_item_FK` FOREIGN KEY (`order_id`) REFERENCES `repair_order` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2970 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='维修项目表';
/*!40101 SET character_set_client = @saved_cs_client */;

